function solve(n, arestas) {
    const adj = Array.from({ length: n }, () => []);
    const indeg = new Array(n).fill(0);
    for (const [a, b] of arestas) {
        adj[a].push(b);
        indeg[b]++;
    }

    const heap = [];
    for (let i = 0; i < n; i++) {
        if (indeg[i] === 0) heap.push(i);
    }

    const siftDown = (h, i) => {
        const len = h.length;
        while (true) {
            let s = i;
            const l = 2 * i + 1, r = 2 * i + 2;
            if (l < len && h[l] < h[s]) s = l;
            if (r < len && h[r] < h[s]) s = r;
            if (s !== i) {
                [h[i], h[s]] = [h[s], h[i]];
                i = s;
            } else break;
        }
    };

    const siftUp = (h, i) => {
        while (i > 0) {
            const p = Math.floor((i - 1) / 2);
            if (h[p] > h[i]) {
                [h[p], h[i]] = [h[i], h[p]];
                i = p;
            } else break;
        }
    };

    const pop = (h) => {
        const top = h[0];
        h[0] = h[h.length - 1];
        h.pop();
        if (h.length > 0) siftDown(h, 0);
        return top;
    };

    for (let i = Math.floor(heap.length / 2) - 1; i >= 0; i--) {
        siftDown(heap, i);
    }

    const result = [];
    while (heap.length > 0) {
        const u = pop(heap);
        result.push(u);
        for (const v of adj[u]) {
            indeg[v]--;
            if (indeg[v] === 0) {
                heap.push(v);
                siftUp(heap, heap.length - 1);
            }
        }
    }

    return result.length === n ? result : null;
