  if (n < 2) return 0;

  // Forward pass: max profit with 1 transaction up to day i
  const forward = new Array(n);
  let minPrice = precos[0];
  let maxProfit = 0;
  for (let i = 0; i < n; i++) {
    minPrice = Math.min(minPrice, precos[i]);
    maxProfit = Math.max(maxProfit, precos[i] - minPrice);
    forward[i] = maxProfit;
  }

  // Backward pass: max profit from day i to end with 1 transaction
  const backward = new Array(n);
  let maxPrice = precos[n - 1];
  maxProfit = 0;
  for (let i = n - 1; i >= 0; i--) {
    maxPrice = Math.max(maxPrice, precos[i]);
    maxProfit = Math.max(maxProfit, maxPrice - precos[i]);
    backward[i] = maxProfit;
  }

  // Combine: max profit with 2 transactions = forward[i] + backward[i]
  let maxTotal = 0;
  for (let i = 0; i < n; i++) {
    maxTotal = Math.max(maxTotal, forward[i] + backward[i]);
  }

  return maxTotal;
}
